<template>
  <AppLayout>
    <div class="mx-auto max-w-7xl space-y-4">
      <PageHeader description="Today, upcoming and overdue visits across ANC, PNC, Palliative Care, Postpartum and Child 6 wk–1 year.">
        <template #title>
          <h1 class="text-lg font-semibold text-gray-900 dark:text-gray-100">Work Orders</h1>
        </template>
        <template #actions>
          <span class="inline-flex items-center gap-1.5 rounded-full bg-teal-50 px-3 py-1 text-xs font-medium text-teal-700 ring-1 ring-teal-100 dark:bg-teal-900/30 dark:text-teal-300 dark:ring-teal-900">
            <LucideIcon name="user-round" class="h-3.5 w-3.5" />
            {{ session.full_name || session.user }} · {{ isPrivileged ? 'Coordinator' : 'CHW Health Worker' }}
          </span>
        </template>
      </PageHeader>

      <!-- Filters: one row above everything they drive. Village / Health
      Worker are coordinator-only - a CHW is always scoped to themselves
      server-side. -->
      <div class="flex flex-wrap items-end gap-3 rounded-xl bg-white p-3 shadow-sm ring-1 ring-gray-200 dark:bg-gray-900 dark:ring-gray-800">
        <div v-for="control in filterControls" :key="control.key" class="w-full" :class="control.width">
          <FormControl
            type="select"
            class="[&_[data-slot=trigger]]:w-full"
            :label="control.label"
            :options="control.options"
            v-model="filters[control.key]"
          />
        </div>
        <Button v-if="hasActiveFilters" variant="ghost" @click="clearFilters">
          <template #prefix>
            <LucideIcon name="x" class="h-4 w-4" />
          </template>
          Clear filters
        </Button>
      </div>

      <div
        v-if="!isPrivileged && summary.health_worker_linked === false"
        class="rounded-xl bg-yellow-50 px-4 py-3 text-sm text-yellow-800 ring-1 ring-yellow-200 dark:bg-yellow-900/20 dark:text-yellow-300 dark:ring-yellow-900"
      >
        No Health Worker record is linked to your login. Ask your coordinator to set the
        <strong>User</strong> field on your Health Worker record so your work order list can show here.
      </div>

      <ErrorMessage v-if="summaryError" :message="summaryError" />

      <!-- Status cards: click to open that bucket's records below; click
      the open one again to close it (same toggle as the Desk page). -->
      <!-- Larger cards: label + icon on top, big count, then a "View
      visits" cue - fixed min height so every card lines up evenly. -->
      <div v-else class="grid grid-cols-1 gap-4 min-[480px]:grid-cols-2 lg:grid-cols-3">
        <button
          v-for="card in STATUS_CARDS"
          :key="card.key"
          type="button"
          :aria-pressed="filters.status === card.key"
          class="group flex min-h-[10rem] flex-col justify-between gap-4 rounded-2xl bg-white p-5 text-left shadow-sm ring-1 transition hover:-translate-y-0.5 hover:shadow-md focus:outline-none focus-visible:ring-2 focus-visible:ring-gray-400 dark:bg-gray-900 sm:p-6"
          :class="filters.status === card.key ? ['ring-2', card.ringClass] : 'ring-gray-200 hover:ring-gray-300 dark:ring-gray-800 dark:hover:ring-gray-700'"
          @click="openStatus(card.key)"
        >
          <span class="flex w-full items-start justify-between gap-3">
            <span class="text-sm font-medium text-gray-600 dark:text-gray-300">{{ card.label }}</span>
            <span class="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl" :class="card.iconClass">
              <LucideIcon :name="card.icon" class="h-5 w-5" />
            </span>
          </span>
          <Skeleton v-if="summaryLoading && !summaryLoaded" width="3.5rem" height="2.25rem" />
          <span v-else class="block text-[2rem] font-bold leading-none tabular-nums text-gray-900 dark:text-gray-100">
            {{ summary[card.key] || 0 }}
          </span>
          <span class="inline-flex items-center gap-1 text-sm font-medium text-gray-700 dark:text-gray-300">
            View visits
            <LucideIcon
              name="arrow-right"
              class="h-4 w-4 transition group-hover:translate-x-0.5"
            />
          </span>
        </button>
      </div>

      <p class="text-center text-sm text-gray-400 dark:text-gray-500">
        Pick a card or a Status above to see its visits.
      </p>
    </div>

    <!-- Drilldown popup, centred over the page (like the Desk page's). It
    is open exactly while a status is selected; closing it clears the
    status. The modal backdrop blocks the page's own filter bar, so the same
    filters (bound to the same values) are repeated at its top. -->
    <Dialog v-model="showDrilldown" :options="{ size: '6xl' }">
      <template #body-title>
        <div class="flex items-center gap-2">
          <span
            v-if="selectedCard"
            class="flex h-8 w-8 flex-shrink-0 items-center justify-center rounded-lg"
            :class="selectedCard.iconClass"
          >
            <LucideIcon :name="selectedCard.icon" class="h-4 w-4" />
          </span>
          <h3 class="text-lg font-semibold text-gray-900 dark:text-gray-100">{{ selectedStatusLabel }}</h3>
          <span
            v-if="!records.loading || records.total"
            class="rounded-full bg-gray-100 px-2 py-0.5 text-xs font-medium tabular-nums text-gray-600 dark:bg-gray-800 dark:text-gray-400"
          >
            {{ records.total }}
          </span>
        </div>
      </template>
      <template #body-content>
      <div class="overflow-hidden rounded-xl ring-1 ring-gray-200 dark:ring-gray-800">
        <div class="flex flex-wrap items-end gap-3 border-b bg-gray-50 px-4 py-3 dark:border-gray-800 dark:bg-gray-800/50">
          <div v-for="control in filterControls" :key="control.key" class="w-full" :class="control.width">
            <FormControl
              type="select"
              class="[&_[data-slot=trigger]]:w-full"
              :label="control.label"
              :options="control.options"
              v-model="filters[control.key]"
            />
          </div>
        </div>

        <div class="flex flex-wrap items-center justify-between gap-3 border-b px-4 py-3 dark:border-gray-800">
          <div class="flex w-full items-center justify-between gap-2">
            <div class="relative flex-1 sm:w-72 sm:flex-none">
              <LucideIcon name="search" class="pointer-events-none absolute left-2.5 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input
                v-model="search"
                type="search"
                placeholder="Search patient on this page"
                class="h-8 w-full rounded-md border-0 bg-gray-100 pl-8 pr-2 text-sm text-gray-900 placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-gray-300 dark:bg-gray-800 dark:text-gray-100 dark:focus:ring-gray-600"
              />
            </div>
            <a
              v-if="records.total"
              :href="excelUrl"
              target="_blank"
              rel="noopener"
              class="inline-flex h-8 flex-shrink-0 items-center gap-1.5 rounded-md bg-green-700 px-3 text-sm font-medium text-white hover:bg-green-800"
            >
              <LucideIcon name="download" class="h-4 w-4" />
              Excel
            </a>
          </div>
        </div>

        <div v-if="summary.by_type?.length" class="flex flex-wrap gap-2 border-b px-4 py-3 dark:border-gray-800">
          <span
            v-for="t in summary.by_type"
            :key="t.key"
            class="rounded-full bg-gray-50 px-2.5 py-1 text-xs text-gray-600 ring-1 ring-gray-200 dark:bg-gray-800 dark:text-gray-300 dark:ring-gray-700"
          >
            {{ t.label }} <span class="font-semibold tabular-nums text-gray-900 dark:text-gray-100">{{ byTypeCountFor(t) }}</span>
          </span>
        </div>

        <ErrorMessage v-if="records.error" class="m-4" :message="records.error" />
        <div v-else-if="records.loading && !records.rows.length" class="space-y-2 p-4">
          <Skeleton v-for="i in 6" :key="i" height="2.25rem" />
        </div>
        <div
          v-else-if="!visibleRows.length"
          class="flex flex-col items-center gap-2 py-12 text-sm text-gray-500 dark:text-gray-400"
        >
          <LucideIcon name="inbox" class="h-8 w-8 text-gray-300 dark:text-gray-600" />
          {{ records.rows.length ? 'No visits match the search / risk filter on this page.' : 'No visits for this selection.' }}
        </div>
        <div v-else class="max-h-[50vh] overflow-auto">
          <table class="w-full min-w-[46rem] text-left text-sm" :class="{ 'opacity-60': records.loading }">
            <thead class="sticky top-0 z-10 bg-gray-50 text-xs uppercase tracking-wide text-gray-500 dark:bg-gray-800 dark:text-gray-400">
              <tr>
                <th class="px-4 py-2.5 font-medium">Patient</th>
                <th class="px-4 py-2.5 font-medium">Visit Type</th>
                <th class="px-4 py-2.5 font-medium">Village</th>
                <th class="px-4 py-2.5 font-medium">Visit Window</th>
                <th class="px-4 py-2.5 font-medium">Status</th>
              </tr>
            </thead>
            <tbody class="divide-y divide-gray-100 dark:divide-gray-800">
              <tr
                v-for="row in visibleRows"
                :key="`${row.doctype}-${row.name}`"
                tabindex="0"
                class="cursor-pointer transition hover:bg-gray-50 focus:bg-gray-50 focus:outline-none dark:hover:bg-gray-800/60 dark:focus:bg-gray-800/60"
                @click="openRecord(row)"
                @keydown.enter="openRecord(row)"
              >
                <td class="whitespace-nowrap px-4 py-2.5 font-medium text-gray-900 dark:text-gray-100">
                  {{ row.patient || row.name }}
                  <span
                    v-if="row.high_risk === 'Yes'"
                    class="ml-2 rounded-full bg-red-100 px-2 py-0.5 text-[10px] font-bold uppercase text-red-700 dark:bg-red-900/40 dark:text-red-300"
                  >
                    High risk
                  </span>
                </td>
                <td class="whitespace-nowrap px-4 py-2.5 text-gray-600 dark:text-gray-300">{{ row.visit_type }}</td>
                <td class="whitespace-nowrap px-4 py-2.5 text-gray-600 dark:text-gray-300">
                  <span v-if="row.village">{{ row.village }}</span>
                  <span v-else class="text-gray-300 dark:text-gray-600">—</span>
                </td>
                <td class="whitespace-nowrap px-4 py-2.5 tabular-nums text-gray-600 dark:text-gray-300">{{ windowRange(row) }}</td>
                <td class="px-4 py-2.5">
                  <span class="rounded-full px-2 py-0.5 text-xs font-semibold" :class="statusBadgeClass(row.status)">
                    {{ row.status }}
                  </span>
                </td>
              </tr>
            </tbody>
          </table>
        </div>

        <div class="flex flex-wrap items-center justify-between gap-3 border-t px-4 py-3 dark:border-gray-800">
          <span class="text-sm text-gray-500 dark:text-gray-400">
            <template v-if="records.total">
              Showing {{ records.start + 1 }}–{{ records.start + records.rows.length }} of {{ records.total }}
            </template>
          </span>
          <div class="flex items-center gap-2">
            <Button :disabled="records.loading || records.start === 0" @click="changePage(-1)">
              <template #prefix>
                <LucideIcon name="chevron-left" class="h-4 w-4" />
              </template>
              Previous
            </Button>
            <Button :disabled="records.loading || records.start + records.rows.length >= records.total" @click="changePage(1)">
              Next
              <template #suffix>
                <LucideIcon name="chevron-right" class="h-4 w-4" />
              </template>
            </Button>
          </div>
        </div>
      </div>
      </template>
    </Dialog>
  </AppLayout>
</template>

<script setup>
import { computed, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { Button, Dialog, ErrorMessage, FormControl, call } from 'frappe-ui'
import AppLayout from '@/layouts/AppLayout.vue'
import PageHeader from '@/components/PageHeader.vue'
import Skeleton from '@/components/Skeleton.vue'
import LucideIcon from '@/components/LucideIcon.vue'
import { session } from '@/data/session'
import { userContextResource } from '@/data/userContext'
import { villagesResource, healthWorkersResource, ALL_VILLAGES, ALL_HEALTH_WORKERS } from '@/data/dashboardFilters'
import { VISIT_TYPES, PAGE_SIZE, STATUS_CARDS, STATUS_OPTIONS, RISK_OPTIONS, statusBadgeClass } from '@/data/workOrders'
import { setPageTitle } from '@/data/pageTitle'
import { goToRecord } from '@/data/openRecord'

setPageTitle('Work Orders')

const router = useRouter()

const isPrivileged = computed(() => !!userContextResource.data?.is_privileged)

const filters = reactive({
  status: '',
  visit_type: '',
  risk: '',
  village: ALL_VILLAGES,
  health_worker: ALL_HEALTH_WORKERS,
})

const hasActiveFilters = computed(
  () =>
    !!(filters.status || filters.visit_type || filters.risk) ||
    filters.village !== ALL_VILLAGES ||
    filters.health_worker !== ALL_HEALTH_WORKERS,
)

function clearFilters() {
  Object.assign(filters, {
    status: '',
    visit_type: '',
    risk: '',
    village: ALL_VILLAGES,
    health_worker: ALL_HEALTH_WORKERS,
  })
}

const visitTypeOptions = [{ label: 'All Visit Types', value: '' }, ...VISIT_TYPES.map((v) => ({ label: v, value: v }))]
const villageOptions = computed(() => [
  { label: ALL_VILLAGES, value: ALL_VILLAGES },
  ...(villagesResource.data || []).map((v) => ({ label: v, value: v })),
])
const healthWorkerOptions = computed(() => [
  { label: ALL_HEALTH_WORKERS, value: ALL_HEALTH_WORKERS },
  ...(healthWorkersResource.data || []).map((v) => ({ label: v, value: v })),
])

// One list, rendered both on the page and at the top of the popup, so the
// two copies can never drift apart. Village / Health Worker are
// coordinator-only - a CHW is always scoped to themselves server-side.
const filterControls = computed(() => [
  { key: 'status', label: 'Status', options: STATUS_OPTIONS, width: 'min-[480px]:w-44' },
  { key: 'visit_type', label: 'Visit Type', options: visitTypeOptions, width: 'min-[480px]:w-52' },
  { key: 'risk', label: 'Risk', options: RISK_OPTIONS, width: 'min-[480px]:w-36' },
  ...(isPrivileged.value
    ? [
        { key: 'village', label: 'Village', options: villageOptions.value, width: 'min-[480px]:w-44' },
        { key: 'health_worker', label: 'Health Worker', options: healthWorkerOptions.value, width: 'min-[480px]:w-52' },
      ]
    : []),
])

// Village / Health Worker options are privileged-only on the backend
// (get_health_workers throws otherwise), so only fetched once we know.
watch(
  isPrivileged,
  (privileged) => {
    if (!privileged) return
    if (!villagesResource.data) villagesResource.fetch()
    if (!healthWorkersResource.data) healthWorkersResource.fetch()
  },
  { immediate: true },
)

// The params every server call shares. visit_type is dropped when empty -
// the backend treats a missing one as "all types".
function scopeParams() {
  return {
    village: filters.village,
    health_worker: filters.health_worker,
    ...(filters.visit_type ? { visit_type: filters.visit_type } : {}),
  }
}

function errorText(e, fallback) {
  return e?.messages?.join(', ') || e?.message || fallback
}

// ---- Summary (the 6 cards) ----
// call() with explicit args rather than a shared useCall().fetch(args):
// fetch is useCall's execute(), which ignores any args passed to it, so
// the filters (and, for records, the status) never reached the server
// before. A request counter drops responses overtaken by a newer request.
const emptySummary = { health_worker_linked: true, this_week: 0, today: 0, upcoming: 0, overdue: 0, completed: 0, high_risk: 0, by_type: [] }
const summary = ref(emptySummary)
const summaryLoading = ref(false)
const summaryLoaded = ref(false)
const summaryError = ref(null)
let summaryRequestId = 0

async function loadSummary() {
  const requestId = ++summaryRequestId
  summaryLoading.value = true
  summaryError.value = null
  try {
    const data = await call('chw.api.get_chw_work_order_summary', scopeParams())
    if (requestId !== summaryRequestId) return
    summary.value = data || emptySummary
    summaryLoaded.value = true
  } catch (e) {
    if (requestId !== summaryRequestId) return
    summaryError.value = errorText(e, 'Could not load the work order summary.')
  } finally {
    if (requestId === summaryRequestId) summaryLoading.value = false
  }
}

// ---- Records for the selected status ----
const records = reactive({ rows: [], total: 0, start: 0, loading: false, error: null })
let recordsRequestId = 0

async function loadRecords() {
  const requestId = ++recordsRequestId
  // Landing view (nothing picked yet) - no fetch, same as the Desk page
  // keeping its drilldown closed until a card is picked.
  if (!filters.status) {
    Object.assign(records, { rows: [], total: 0, start: 0, loading: false, error: null })
    return
  }
  records.loading = true
  records.error = null
  try {
    const data = await call('chw.api.chw_work_order_drilldown', {
      status: filters.status,
      ...scopeParams(),
      page_length: PAGE_SIZE,
      start: records.start,
    })
    if (requestId !== recordsRequestId) return
    records.rows = data?.records || []
    records.total = data?.total_count ?? records.rows.length
  } catch (e) {
    if (requestId !== recordsRequestId) return
    records.error = errorText(e, 'Could not load visits.')
  } finally {
    if (requestId === recordsRequestId) records.loading = false
  }
}

function changePage(direction) {
  records.start = Math.max(0, records.start + direction * PAGE_SIZE)
  loadRecords()
}

loadSummary()

// Scope changes refresh both and go back to page 1.
watch(
  () => [filters.village, filters.health_worker, filters.visit_type],
  () => {
    records.start = 0
    loadSummary()
    loadRecords()
  },
)

// A newly picked status starts on page 1 with a fresh search.
watch(
  () => filters.status,
  () => {
    records.start = 0
    search.value = ''
    loadRecords()
  },
)

function openStatus(key) {
  filters.status = key
}

// The popup is open exactly while a status is selected - a card click or
// the Status filter opens it; closing it (X, Esc, backdrop) clears the
// status, which also un-highlights the card and empties the records.
const showDrilldown = computed({
  get: () => !!filters.status,
  set: (open) => {
    if (!open) filters.status = ''
  },
})

const selectedCard = computed(() => STATUS_CARDS.find((c) => c.key === filters.status) || null)

const selectedStatusLabel = computed(
  () => STATUS_OPTIONS.find((o) => o.value === filters.status)?.label || '',
)

function byTypeCountFor(t) {
  if (filters.status === 'all') return (t.this_week || 0) + (t.overdue || 0)
  return t[filters.status] || 0
}

// Risk and search only narrow the page already loaded - same as the Desk
// page's Risk filter, no extra server round trip.
const search = ref('')
const visibleRows = computed(() => {
  let rows = records.rows
  if (filters.risk === 'high_risk') rows = rows.filter((r) => r.high_risk === 'Yes')
  else if (filters.risk === 'normal') rows = rows.filter((r) => r.high_risk !== 'Yes')
  const q = search.value.trim().toLowerCase()
  if (q) rows = rows.filter((r) => `${r.patient || ''} ${r.name || ''}`.toLowerCase().includes(q))
  return rows
})

// Matches the page on screen exactly - same status, scope, page and Risk.
const excelUrl = computed(() => {
  const params = new URLSearchParams({
    status: filters.status,
    village: filters.village || '',
    health_worker: filters.health_worker || '',
    visit_type: filters.visit_type || '',
    page_length: PAGE_SIZE,
    start: records.start,
    risk: filters.risk || '',
  })
  return `/api/method/chw.api.chw_work_order_drilldown_excel?${params.toString()}`
})

function openRecord(row) {
  goToRecord(router, row.doctype, row.name)
}

// ---- Dates ----
// Parsed as local calendar dates: new Date('2026-07-08') is UTC midnight,
// which can land on the previous day once shown in local time.
function parseDate(value) {
  const [y, m, d] = String(value).slice(0, 10).split('-').map(Number)
  return y && m && d ? new Date(y, m - 1, d) : null
}

function formatDate(date) {
  return date.toLocaleDateString(undefined, { day: '2-digit', month: 'short', year: 'numeric' })
}

// Always a full range - with no stored window start (older records, or the
// manual phase's typed date), falls back to 30 days before the due date,
// same as the Desk page.
function windowRange(row) {
  const due = row.due_date ? parseDate(row.due_date) : null
  if (!due) return '—'
  let from = row.from_date ? parseDate(row.from_date) : null
  if (!from) {
    from = new Date(due)
    from.setDate(from.getDate() - 30)
  }
  return `${formatDate(from)} – ${formatDate(due)}`
}
</script>
