export function statusBadgeClass(rowStatus) {
  return (
    STATUS_CARDS.find((c) => c.rowLabel === rowStatus)?.badgeClass ||
    'bg-gray-100 text-gray-700 dark:bg-gray-800 dark:text-gray-300'
  )
}
